  ["2154b4000ca68f04"] = { "Ho perso il mio ⟦Ring of Eternal Justice=Anello dell'Eterna Giustizia⟧. Puoi sostituirmelo?", "." },
  ["2155755f2f2da197"] = { "Oh aspetta, quella è la tenda di Hollee... ed è vuota.", "." },
  ["2156a14b75fd8e61"] = { "<Valenna distoglie brevemente lo sguardo prima di tornare a guardarti, esitante.>\n\nLo Shal'nan era il migliore di tutti noi. Fu lui a difendere il nostro popolo dalla follia e dall'oppressione a Eldre'Thalas, quasi diecimila anni fa. Fu lo Shal'nan a guidarci attraverso il mare inesplorato per sfuggire alla vendetta assassina dei nostri antichi nemici.\n\nFu lo Shal'nan a stringere il patto d'amicizia con gli spiriti del vento che ci permise di ascendere a Skywall... e di sopravvivere.\n\nFu sempre un capo al servizio del suo popolo, anche dopo aver rinunciato alla sua posizione di potere ed essersi ritirato.", "." },
  ["21595ab6eba23308"] = { "Voglio esaminare questo pilastro.", "." },
