  ["215f00dae4250fb0"] = { "Ricorda, tutte le cose sono legate. Se le bestie sparissero dalla terra, la nostra gente morirebbe di una grande solitudine dello spirito, perché ciò che accade alle bestie accade anche ai tauren. Ciò che colpisce Azeroth colpisce tutti coloro che la abitano.", "." },
  ["21681132e82919cd"] = { "Il medaglione di %s va in frantumi.", "." },
  ["216f6c41d032c23d"] = { "Il ⟦Pool of Tears=Bacino delle Lacrime⟧ nella ⟦Swamp of Sorrows=Palude del Dolore⟧ custodisce antichi scrigni chiusi a chiave, perduti in un'altra era.", "." },
  ["216facfc6e36df1a"] = { "{name}, non fare male A-Me. A-Me amica.", "." },
