  ["219a7e8bf92536d4"] = { "Athrikus ti indica mentre urla parole che ti graffiano l'interno delle orecchie. Sono l'ultima cosa che senti.", "." },
  ["219b661bafb061b3"] = { "La mia risposta è Ysera.", "." },
  ["219c441b6751ad70"] = { "Ti prego, aiutami ad attraversare questa foresta maledetta, {race}.", "." },
  ["21abc9d4e46f975a"] = { "NOOOO!! No!", "." },
  ["21ad31bf1ea522a3"] = { "Allora, <ragazzo/ragazza>, pensi di avere la stoffa per difendere l'⟦Alliance=Alleanza⟧ contro l'⟦Horde=Orda⟧ nella ⟦Alterac Valley=Valle d'Alterac⟧? Molto bene, allora vorrai parlare con il nostro Glordrum Steelbeard, qui a ⟦Ironforge=Forgiardente⟧. Lo troverai a studiare strategie sul tavolo da guerra nel Salone delle Armi.", "." },
  ["21af53fd7bedaa81"] = { "La mia programmazione non mi consente di abbassare il prezzo di nessun articolo.", "." },
  ["21b0a4264f1fcdab"] = { "Le locande sono luoghi dove puoi riposare dopo le tue avventure. Se non ti fermi in una locanda come questa, non avrai recuperato del tutto le forze quando ti avventurerai di nuovo nelle terre selvagge.\n\nIn qualsiasi locanda puoi anche ottenere una Pietra del Ritorno e, più tardi, quando vorrai riposare, potrai usarla per tornare alla locanda in cui l'hai ottenuta.", "." },
  ["21b312810089fb55"] = { "Forse tu riesci meglio di vecchio capo a riprendere preziosa reliquia Gordok da inquietante principe degli ⟦Highborne=Alti Nobili⟧!", "." },
  ["21bbf93fc058b4b7"] = { "Quale Guardiano? Non capisco niente di tutto questo.", "." },
  ["21bfd847ff4f850f"] = { "PER L'ONORE!", "." },
  ["21d4e5f8683a3f45"] = { "Stolti! Vi credete trionfatori? Avete solo fatto un passo in più verso l'abisso!", "." },
  ["21d586a7fd03c6fa"] = { "Novità di quest'anno: il ⟦PX-238 Winter Wondervolt=Trasmutometro Invernale PX-238⟧. Fatti avanti, non avere paura!\n\nE firma questi moduli prima di provarlo: stiamo ancora sistemando qualche difetto di questo coso...", "." },
  ["21d7bc6549c462e8"] = { "Attendiamo una partita di uova di drago nero dalle ⟦Burning Steppes=Steppe Ardenti⟧. Crediamo che, studiandole, faremo enormi progressi nelle nostre conoscenze.", "." },
  ["21da45b0cf853349"] = { "L'altro giorno ho sentito Regnus Thundergranite, nell'Salone delle Armi, vantarsi di un nuovo trofeo per la sua tana. Se cerchi l'addestramento di un cacciatore esperto, Regnus è quello giusto.", "." },
  ["21ed3e29db13698f"] = { "Oh, santo cielo, non di nuovo... Siediti, <giovanotto/signorina>.\n\nDi sicuro Rutgar ti ha già raccontato parte della storia, quindi ti risparmio i dettagli noiosi e vengo dritto al sodo.", "." },
  ["21f2c6ec74f55d10"] = { "La vostra morte alimenta la mia forza!", "." },
  ["21f50b800008877b"] = { "La Torre di Brinarossa è stata distrutta dall'⟦Alliance=Alleanza⟧!", "." },
  ["21f6fcb886c2bc76"] = { "<La testa di Othmar ti osserva da poco lontano.>\n\nChe... cosa... vuoi...\n\n<Lurido/Lurida>... {race}...", "." },
